from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    out: list[str] = []

    def add_months(y: int, m: int, k: int) -> tuple[int, int]:
        idx = y * 12 + (m - 1) + k
        return idx // 12, idx % 12 + 1

    if kind == "DAILY":
        k = int(parts[1])
        d = s
        while len(out) < count:
            out.append(d.isoformat())
            d += timedelta(days=k)
        return out

    if kind == "WEEKLY":
        k = int(parts[1])
        codes = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
        wds = sorted(codes[c] for c in parts[2].split(","))
        monday = s - timedelta(days=s.weekday())
        w = 0
        while len(out) < count:
            week_start = monday + timedelta(weeks=w * k)
            for wd in wds:
                d = week_start + timedelta(days=wd)
                if d >= s:
                    out.append(d.isoformat())
                    if len(out) == count:
                        return out
            w += 1
        return out

    if kind == "MONTHLY":
        k = int(parts[1])
        spec = parts[2]
        n = 0
        while len(out) < count:
            y, m = add_months(s.year, s.month, n * k)
            if spec_is_nth := (len(parts) == 4):
                nth = int(spec)
                wd = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}[parts[3]]
                ndays = calendar.monthrange(y, m)[1]
                days = [date(y, m, i) for i in range(1, ndays + 1) if date(y, m, i).weekday() == wd]
                if nth == -1:
                    cand = days[-1] if days else None
                else:
                    cand = days[nth - 1] if 0 < nth <= len(days) else None
                if cand is not None and cand >= s:
                    out.append(cand.isoformat())
            else:
                dnum = int(spec)
                ndays = calendar.monthrange(y, m)[1]
                if dnum == -1:
                    day = ndays
                else:
                    day = dnum if dnum <= ndays else None
                if day is not None:
                    cand = date(y, m, day)
                    if cand >= s:
                        out.append(cand.isoformat())
            n += 1
        return out[:count]

    if kind == "YEARLY":
        k = int(parts[1])
        mm, dd = (int(x) for x in parts[2].split("-"))
        y = s.year
        while len(out) < count:
            if (y - s.year) % k == 0:
                try:
                    cand = date(y, mm, dd)
                except ValueError:
                    cand = None
                if cand is not None and cand >= s:
                    out.append(cand.isoformat())
            y += 1
        return out

    return out
